Mistral R1:
# Qualitative Code

class SummaryRefinement:
    def __init__(self, contributions):
        self.contributions = contributions

    def extract_key_points(self):
        key_points = {
            mental_illness: False,
            danger: False,
            confinement: False,
            example: None
        }

        for contribution in self.contributions:
            if mental illness in contribution:
                key_points[mental_illness] = True
            if danger in contribution:
                key_points[danger] = True
            if confinement in contribution or institutionalization in contribution:
                key_points[confinement] = True
            if Scott Willingham in contribution:
                key_points[example] = Scott Willingham

        return key_points

    def create_refined_summary(self):
        key_points = self.extract_key_points()
        summary = The occupiers

        if key_points[example]:
            summary += f (e.g., {key_points['example']})

        summary +=  are considered

        if key_points[mental_illness]:
            summary +=  mentally ill

        if key_points[danger]:
            if key_points[mental_illness]:
                summary +=  and
            summary +=  dangerous

        if key_points[confinement]:
            summary += , leading to recommendations for confinement or institutionalization.

        return summary

# Example usage
contributions = [
    LLM-1 highlights mental illness.,
    LLM-2 emphasizes confinement.,
    LLM-3 mentions danger.,
    LLM-5 mentions Scott Willingham and institutionalization.
]

refinement = SummaryRefinement(contributions)
refined_summary = refinement.create_refined_summary()
print(refined_summary)

