    { name: Genetics, isInnate: true },
    { name: Environment, isInnate: false },
    { name: Education, isInnate: false },
    { name: Personality, isInnate: true }
];

// Analyze influences
influences.forEach(influence => {
    console.log(`${influence.name} is categorized as: ${categorizeInfluence(influence)}`);
});

